from typing import List

class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        candidates = []
        for row, limit in zip(grid, limits):
            if limit > 0:
                # Sort the row in place to optimize time and avoid unnecessary memory allocation
                row.sort(reverse=True)
                candidates.extend(row[:limit])

        # Sort all the collected candidates in descending order
        candidates.sort(reverse=True)

        # Sum the largest k elements
        return sum(candidates[:k])
